import sys, subprocess, re
sys.path.insert(0, "/tmp/iconvtest/mock"); sys.path.insert(0, "/home/tirandagan.guest/naive-arm/output/annotation")
from pash_annotations.annotation_generation.annotation_generators.ParallelizabilityInfoGenerator_Interface import Opt, Inv
from ParallelizabilityInfoGeneratorIconv import ParallelizabilityInfoGeneratorIconv as P
from InputOutputInfoGeneratorIconv import InputOutputInfoGeneratorIconv as IO

def par(fo, ops=()):
