print("PAR latin1->utf8    ", par([Opt("-f","ISO-8859-1"),Opt("-t","UTF-8")]))
print("PAR utf8->ascii//TR ", par([Opt("-f","utf-8"),Opt("-t","ascii//TRANSLIT")]))
print("PAR ->UTF-16        ", par([Opt("-f","UTF-8"),Opt("-t","UTF-16")]))
print("PAR UTF-16->        ", par([Opt("-f","UTF-16"),Opt("-t","UTF-8")]))
print("PAR ->ISO-2022-JP   ", par([Opt("-f","UTF-8"),Opt("-t","ISO-2022-JP")]))
print("PAR -c cp1252->utf8 ", par([Opt("-c"),Opt("-f","CP1252"),Opt("-t","UTF-8")]))
print("PAR -l              ", par([Opt("-l")]))
print("PAR unreadable arg  ", par([Opt("-f",None)]))

# empirical check of the safe list against every name iconv knows
names = subprocess.run(["iconv","-l"], capture_output=True, text=True).stdout.split()
names = [n.rstrip("/") for n in names]
safe = [n for n in names if P._is_safe_encoding(n)]
probe = b"a\nb\n\xc3\xa9\n"  # includes a non-ASCII char so shift-state encodings would emit escapes
bad = []
for n in safe:
    for direction in (["-f","UTF-8","-t",n+"//TRANSLIT"], ["-f",n,"-t","UTF-8"]):
        r = subprocess.run(["iconv"]+direction, input=b"a\nb\n", capture_output=True)
        if r.returncode != 0 or r.stdout != b"a\nb\n":
            bad.append((n, direction, r.returncode, r.stdout)); break
    # per-chunk vs whole: converting lines separately must equal converting at once
    r1 = subprocess.run(["iconv","-f","UTF-8","-t",n+"//TRANSLIT"], input=probe, capture_output=True).stdout
    r2 = b"".join(subprocess.run(["iconv","-f","UTF-8","-t",n+"//TRANSLIT"], input=line, capture_output=True).stdout for line in probe.splitlines(keepends=True))
    if r1 != r2: bad.append((n, "chunk-mismatch", r1, r2))
print(f"{len(safe)} of {len(names)} names matched as safe; failures: {len(bad)}")
for b in bad[:20]: print("  BAD", b)
unsafe_kw = ["UTF-16","UTF-32","UTF-7","UCS","2022","UTF-16LE","UNICODE","EBCDIC","IBM037","CP037"]
print("unsafe matched:", [n for n in safe if any(k in n for k in unsafe_kw)])
print("sample safe:", safe[:10], "...")
EOF
